import{_ as a,o as e,c as i,a2 as t}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"CLI Reference","description":"","frontmatter":{},"headers":[],"relativePath":"liteshield-xdp/user-guide/cli.md","filePath":"liteshield-xdp/user-guide/cli.md","lastUpdated":null}'),n={name:"liteshield-xdp/user-guide/cli.md"};function l(d,s,o,h,p,c){return e(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><p><code>liteshield</code> is the single command-line interface for LiteShield XDP. It loads and detaches the XDP program, manages the whitelist/blacklist maps live, and hot-reloads configuration. Every command that touches BPF state requires root.</p><nav class="table-of-contents"><ul><li><a href="#lifecycle">Lifecycle</a><ul><li><a href="#load">load</a></li><li><a href="#unload">unload</a></li></ul></li><li><a href="#inspection">Inspection</a><ul><li><a href="#status">status</a></li></ul></li><li><a href="#whitelist">Whitelist</a><ul><li><a href="#whitelist-add">whitelist add</a></li><li><a href="#whitelist-remove">whitelist remove</a></li><li><a href="#whitelist-list">whitelist list</a></li></ul></li><li><a href="#blacklist">Blacklist</a><ul><li><a href="#blacklist-add">blacklist add</a></li><li><a href="#blacklist-remove">blacklist remove</a></li><li><a href="#blacklist-list">blacklist list</a></li></ul></li><li><a href="#configuration">Configuration</a><ul><li><a href="#config">config</a></li></ul></li><li><a href="#informational">Informational</a><ul><li><a href="#version">version</a></li><li><a href="#help">help</a></li></ul></li><li><a href="#command-quick-reference">Command Quick Reference</a></li></ul></nav><div class="info custom-block"><p class="custom-block-title">Root required</p><p>All commands except <code>status</code>, <code>version</code>, and <code>help</code> must run as root (<code>sudo</code>). BPF map and link operations require <code>CAP_BPF</code>/<code>CAP_SYS_ADMIN</code>, which in practice means euid 0.</p></div><hr><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><h3 id="load" tabindex="-1"><code>load</code> <a class="header-anchor" href="#load" aria-label="Permalink to &quot;\`load\`&quot;">​</a></h3><p>Attach the XDP program to the configured interface and show the live status screen.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> load</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--stats-off] [--no-tui] [--config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">path</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><code>--stats-off</code></td><td>Attach, then show a static screen — no per-second stats polling (for very small machines)</td></tr><tr><td><code>--no-tui</code></td><td>Load and exit immediately (used by the systemd unit)</td></tr><tr><td><code>--config</code></td><td>Path to a non-default config file (default <code>/etc/liteshield/liteshield.yaml</code>)</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield load</span></span>
<span class="line"><span>LiteShield XDP is protecting eth0 (native mode).</span></span>
<span class="line"><span>XDP stays loaded after you quit. Use \`liteshield unload\` to stop.</span></span>
<span class="line"><span></span></span>
<span class="line"><span> ◆ LiteShield XDP ACTIVE  eth0  up 00:02:14</span></span>
<span class="line"><span>   ...</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield load --no-tui</span></span>
<span class="line"><span>LiteShield XDP loaded on eth0 (native mode).</span></span></code></pre></div><p><strong>When to use:</strong> First start after installation, interactive monitoring sessions, or manually re-attaching after <code>unload</code>. The systemd service uses <code>load --no-tui</code>.</p><div class="tip custom-block"><p class="custom-block-title">Quitting keeps protection running</p><p><code>Ctrl-C</code> exits the status screen only. The XDP program stays attached until you run <code>liteshield unload</code> or stop the service.</p></div><hr><h3 id="unload" tabindex="-1"><code>unload</code> <a class="header-anchor" href="#unload" aria-label="Permalink to &quot;\`unload\`&quot;">​</a></h3><p>Detach the XDP program and remove all pinned BPF state.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unload</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield unload</span></span>
<span class="line"><span>LiteShield XDP unloaded.</span></span></code></pre></div><p><strong>When to use:</strong> Before uninstalling, before changing the protected interface, or to temporarily disable all enforcement. Unloading clears counters, per-IP state, and auto-bans — manual whitelist/blacklist entries are also dropped, so re-add them after the next <code>load</code>.</p><hr><h2 id="inspection" tabindex="-1">Inspection <a class="header-anchor" href="#inspection" aria-label="Permalink to &quot;Inspection&quot;">​</a></h2><h3 id="status" tabindex="-1"><code>status</code> <a class="header-anchor" href="#status" aria-label="Permalink to &quot;\`status\`&quot;">​</a></h3><p>Show whether LiteShield is loaded, plus a counters snapshot.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield status</span></span>
<span class="line"><span>LiteShield XDP is loaded.</span></span>
<span class="line"><span>  Packets: 301442981 rx (300238425 passed, 1204556 dropped)</span></span>
<span class="line"><span>  Rule drops: SYN 812110 | UDP 390021 | ICMP 2425 | PPS 0 | NewSrc 0 | Ban 0</span></span>
<span class="line"><span>  Lists: whitelist hits 1204 | blacklist hits 88 | active bans 3</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ liteshield status</span></span>
<span class="line"><span>LiteShield XDP is NOT loaded.</span></span>
<span class="line"><span>$ echo $?</span></span>
<span class="line"><span>1</span></span></code></pre></div><p><strong>When to use:</strong> The first thing you run when something feels off, and in monitoring scripts — exit code is <code>0</code> when loaded, <code>1</code> when not.</p><hr><h2 id="whitelist" tabindex="-1">Whitelist <a class="header-anchor" href="#whitelist" aria-label="Permalink to &quot;Whitelist&quot;">​</a></h2><p>Whitelisted sources always pass — no rate limits, no bans. Entries live in a kernel HASH map (max 65,536) and take effect immediately, without reloading.</p><h3 id="whitelist-add" tabindex="-1"><code>whitelist add</code> <a class="header-anchor" href="#whitelist-add" aria-label="Permalink to &quot;\`whitelist add\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whitelist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ip</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cidr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield whitelist add 10.0.0.0/24</span></span>
<span class="line"><span>whitelist add: 10.0.0.0/24 (256 address(es))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo liteshield whitelist add 203.0.113.10</span></span>
<span class="line"><span>whitelist add: 203.0.113.10 (1 address(es))</span></span></code></pre></div><p><strong>When to use:</strong> Exempt your office IP, monitoring probes, upstream load balancers, and health checkers so they are never rate-limited or auto-banned.</p><div class="warning custom-block"><p class="custom-block-title">CIDRs are expanded, not matched</p><p>LiteShield uses HASH maps, not LPM tries. A CIDR is expanded into individual addresses at insert time — the maximum is <code>/24</code> (256 addresses). A <code>/16</code> would need 65,536 entries and is rejected.</p></div><hr><h3 id="whitelist-remove" tabindex="-1"><code>whitelist remove</code> <a class="header-anchor" href="#whitelist-remove" aria-label="Permalink to &quot;\`whitelist remove\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whitelist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ip</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cidr</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield whitelist remove 10.0.0.0/24</span></span>
<span class="line"><span>whitelist remove: 10.0.0.0/24 (256 address(es))</span></span></code></pre></div><hr><h3 id="whitelist-list" tabindex="-1"><code>whitelist list</code> <a class="header-anchor" href="#whitelist-list" aria-label="Permalink to &quot;\`whitelist list\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whitelist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield whitelist list</span></span>
<span class="line"><span>10.0.0.1</span></span>
<span class="line"><span>10.0.0.2</span></span>
<span class="line"><span>203.0.113.10</span></span></code></pre></div><p><strong>When to use:</strong> Audit who is exempt before tightening thresholds. Works for both IPv4 and IPv6 entries.</p><hr><h2 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h2><p>Blacklisted sources are always dropped. Bans are permanent or timed; timed entries use a <code>CLOCK_MONOTONIC</code> deadline — the same clock the BPF program reads — so expiry is exact and survives userspace restarts.</p><h3 id="blacklist-add" tabindex="-1"><code>blacklist add</code> <a class="header-anchor" href="#blacklist-add" aria-label="Permalink to &quot;\`blacklist add\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blacklist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [duration_sec]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Argument</th><th>Description</th></tr></thead><tbody><tr><td><code>&lt;ip&gt;</code></td><td>IPv4 or IPv6 address (single address only, no CIDR)</td></tr><tr><td><code>[duration_sec]</code></td><td>Ban length in seconds. <code>0</code> or omitted = permanent</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield blacklist add 203.0.113.7 3600</span></span>
<span class="line"><span>blacklisted 203.0.113.7 for 3600s</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ sudo liteshield blacklist add 198.51.100.23</span></span>
<span class="line"><span>blacklisted 198.51.100.23 permanently</span></span></code></pre></div><p><strong>When to use:</strong> Kill a specific attacker immediately, or pre-ban known-bad ranges&#39; individual IPs during an incident. For floods from many sources, rely on auto-ban instead — manual bans don&#39;t scale to thousands of spoofed IPs.</p><hr><h3 id="blacklist-remove" tabindex="-1"><code>blacklist remove</code> <a class="header-anchor" href="#blacklist-remove" aria-label="Permalink to &quot;\`blacklist remove\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blacklist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">p</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield blacklist remove 203.0.113.7</span></span>
<span class="line"><span>removed 203.0.113.7 from blacklist</span></span></code></pre></div><hr><h3 id="blacklist-list" tabindex="-1"><code>blacklist list</code> <a class="header-anchor" href="#blacklist-list" aria-label="Permalink to &quot;\`blacklist list\`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blacklist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield blacklist list</span></span>
<span class="line"><span>203.0.113.7                              2814s remaining</span></span>
<span class="line"><span>198.51.100.23                            permanent</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield blacklist list</span></span>
<span class="line"><span>blacklist is empty</span></span></code></pre></div><p><strong>When to use:</strong> Verify a ban landed, or check remaining time before it expires. Note this lists only <em>manual</em> bans — auto-bans from threshold violations appear in the TUI&#39;s <strong>Active bans</strong> counter, not here.</p><hr><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><h3 id="config" tabindex="-1"><code>config</code> <a class="header-anchor" href="#config" aria-label="Permalink to &quot;\`config\`&quot;">​</a></h3><p>Open the config in <code>$EDITOR</code>, validate it, and hot-reload thresholds into the running instance.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">h</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">]</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ sudo liteshield config</span></span>
<span class="line"><span># (nano opens /etc/liteshield/liteshield.yaml — you edit and save)</span></span>
<span class="line"><span>config applied to the running instance.</span></span></code></pre></div><p>Behavior:</p><ol><li>Creates a default config (Hosting/Balanced) if none exists yet</li><li>Opens <code>$EDITOR</code>, falling back to <code>nano</code> then <code>vi</code></li><li>Validates the file — invalid YAML or bad values abort with an error and nothing is applied</li><li>If LiteShield is loaded, thresholds are written into the live <code>config_map</code>; otherwise the file is saved for the next <code>load</code></li></ol><p><strong>When to use:</strong> Every threshold change. This is the only supported way to tune a running instance.</p><div class="info custom-block"><p class="custom-block-title">What hot-reload applies</p><p>Thresholds, ban duration, and Discord settings are applied live. Changing <code>interface</code> or <code>xdp_mode</code> requires <code>unload</code> + <code>load</code> — the attach point cannot change on a running program.</p></div><hr><h2 id="informational" tabindex="-1">Informational <a class="header-anchor" href="#informational" aria-label="Permalink to &quot;Informational&quot;">​</a></h2><h3 id="version" tabindex="-1"><code>version</code> <a class="header-anchor" href="#version" aria-label="Permalink to &quot;\`version\`&quot;">​</a></h3><p>Print the build version.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> version</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ liteshield version</span></span>
<span class="line"><span>liteshield v1.0.0</span></span></code></pre></div><p><strong>When to use:</strong> Reporting bugs or verifying an upgrade. <code>liteshield --version</code> and <code>liteshield -v</code> are aliases.</p><hr><h3 id="help" tabindex="-1"><code>help</code> <a class="header-anchor" href="#help" aria-label="Permalink to &quot;\`help\`&quot;">​</a></h3><p>Print the usage summary.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">liteshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> help</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ liteshield help</span></span>
<span class="line"><span>LiteShield XDP — minimal XDP firewall</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage:</span></span>
<span class="line"><span>  liteshield load [--stats-off] [--no-tui] [--config PATH]</span></span>
<span class="line"><span>  liteshield unload    Detach the XDP program and remove all state</span></span>
<span class="line"><span>  liteshield status    Show whether LiteShield is loaded plus counters</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><hr><h2 id="command-quick-reference" tabindex="-1">Command Quick Reference <a class="header-anchor" href="#command-quick-reference" aria-label="Permalink to &quot;Command Quick Reference&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Category</th><th>Quick description</th></tr></thead><tbody><tr><td><code>load</code></td><td>Lifecycle</td><td>Attach XDP + live status screen (<code>--no-tui</code> for systemd)</td></tr><tr><td><code>unload</code></td><td>Lifecycle</td><td>Detach XDP and clear all state</td></tr><tr><td><code>status</code></td><td>Inspection</td><td>Loaded? + counters snapshot (exit 0/1)</td></tr><tr><td><code>whitelist add</code></td><td>Whitelist</td><td>Exempt an IP or ≤/24 CIDR</td></tr><tr><td><code>whitelist remove</code></td><td>Whitelist</td><td>Remove an exemption</td></tr><tr><td><code>whitelist list</code></td><td>Whitelist</td><td>List whitelisted addresses</td></tr><tr><td><code>blacklist add</code></td><td>Blacklist</td><td>Ban an IP (timed or permanent)</td></tr><tr><td><code>blacklist remove</code></td><td>Blacklist</td><td>Remove a ban</td></tr><tr><td><code>blacklist list</code></td><td>Blacklist</td><td>List bans with remaining time</td></tr><tr><td><code>config</code></td><td>Configuration</td><td>Edit YAML in <code>$EDITOR</code>, hot-reload</td></tr><tr><td><code>version</code></td><td>Informational</td><td>Print build version</td></tr><tr><td><code>help</code></td><td>Informational</td><td>Usage summary</td></tr></tbody></table>`,88)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
